#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
#define BITSET128 bitset<128>
unordered_map<BITSET128, int> node_id; int N, total, P[7][7], dp_state[2][70003], transition[70003][128], probability[128], inv100;

int mod_pow(long long base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % MOD;
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int dfs(BITSET128 &x) {
    if (node_id.count(x)) return node_id[x];
    int id = ++total;
    node_id[x] = id;
    BITSET128 tmp[7], temp;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < (1 << N); ++j) {
            tmp[i][j | (1 << i)] = tmp[i][j | (1 << i)] | x[j];
        }
    }
    for (int mask = 0; mask < (1 << N); ++mask) {
        temp = x;
        for (int j = 0; j < N; ++j) {
            if (mask & (1 << j)) {
                temp |= tmp[j];
            }
        }
        transition[id][mask] = dfs(temp);
    }
    return id;
}

int main() {
    cin >> N;
    BITSET128 start; start.set(0);
    dfs(start);
    inv100 = mod_pow(100, MOD - 2);
    cerr << node_id.size() << endl;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> P[i][j];

    dp_state[0][1] = 1;
    int current_layer = 0;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < (1 << N); ++j) {
            probability[j] = 1;
            for (int k = 0; k < N; ++k) {
                int p_value = (j & (1 << k)) ? P[i][k] : 100 - P[i][k];
                probability[j] = (long long)probability[j] * inv100 % MOD * p_value % MOD;
            }
        }
        memset(dp_state[current_layer ^ 1], 0, sizeof(dp_state[current_layer ^ 1]));
        for (int j = 1; j <= total; ++j) {
            if (dp_state[current_layer][j]) {
                for (int k = 0; k < (1 << N); ++k) {
                    int t = transition[j][k];
                    dp_state[current_layer ^ 1][t] = (dp_state[current_layer ^ 1][t] + (long long)dp_state[current_layer][j] * probability[k]) % MOD;
                }
            }
        }
        current_layer ^= 1;
    }
    BITSET128 final_mask; final_mask.set();
    cout << dp_state[current_layer][node_id[final_mask]] << endl;
    return 0;
}
